"""Synthetic parsers that exercise the plugin contract (SPEC section 13).

These objects are published as real entry points by the ``install_dist``
fixture, so discovery runs through ``importlib.metadata`` rather than a
monkeypatched shortcut. Annotating the well-behaved instances as ``Parser``
also makes ``mypy --strict`` check them against the published protocol.
"""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass

from logsift.plugin import API_VERSION, Parser
from logsift.record import Level, ParseResult


@dataclass
class RecordingParser:
    """A well-behaved parser: every non-empty line becomes a message."""

    api_version: int = API_VERSION
    name: str = "simple"
    priority: int = 10
    columns: Sequence[str] = ("ts", "message")

    def can_parse(self, sample: Sequence[str]) -> bool:
        return bool(sample)

    def parse(self, line: str) -> ParseResult | None:
        if not line:
            return None
        return ParseResult(ts=None, level=Level.INFO, message=line, fields={})


@dataclass
class AlwaysRaises(RecordingParser):
    """Raises on every line, so the circuit breaker of SPEC 4.3 fires."""

    name: str = "always-raises"

    def parse(self, line: str) -> ParseResult | None:
        raise RuntimeError("parser exploded")


@dataclass
class Intermittent(RecordingParser):
    """Raises only on lines carrying ``boom``; the run must still complete."""

    name: str = "intermittent"

    def parse(self, line: str) -> ParseResult | None:
        if "boom" in line:
            raise ValueError("bad line")
        return super().parse(line)


@dataclass
class CanParseRaises(RecordingParser):
    """Disqualifies itself for a source by raising from ``can_parse``."""

    name: str = "bad-can-parse"

    def can_parse(self, sample: Sequence[str]) -> bool:
        raise ValueError("sniff exploded")


@dataclass
class CollidingFields(RecordingParser):
    """Emits field names reserved by the core, per SPEC 4.5."""

    name: str = "colliding-fields"
    columns: Sequence[str] = ("message", "lineno")

    def parse(self, line: str) -> ParseResult | None:
        fields: dict[str, object] = {"message": "shadow", "lineno": -1, "app": "demo"}
        return ParseResult(ts=None, level=None, message=line, fields=fields)


@dataclass
class WrongApiVersion(RecordingParser):
    """Declares an api_version the core does not implement."""

    api_version: int = API_VERSION + 1
    name: str = "wrong-api"


@dataclass
class MalformedName(RecordingParser):
    """Declares a name outside the documented ``[a-z0-9_-]+`` shape."""

    name: str = "Bad Name!"


class MissingPriority:
    """Omits ``priority``, so validation must name the missing attribute."""

    api_version = API_VERSION
    name = "missing-priority"
    columns: Sequence[str] = ("message",)

    def can_parse(self, sample: Sequence[str]) -> bool:
        return True

    def parse(self, line: str) -> ParseResult | None:
        return ParseResult(ts=None, level=None, message=line, fields={})


SIMPLE: Parser = RecordingParser()
ALWAYS_RAISES: Parser = AlwaysRaises()
INTERMITTENT: Parser = Intermittent()
CAN_PARSE_RAISES: Parser = CanParseRaises()
COLLIDING_FIELDS: Parser = CollidingFields()
WRONG_API: Parser = WrongApiVersion()
BAD_NAME: Parser = MalformedName()
MISSING_ATTRIBUTE = MissingPriority()

# Two distributions publishing one name, at different priorities (SPEC 4.4).
DUP_HIGH: Parser = RecordingParser(name="dup", priority=60)
DUP_LOW: Parser = RecordingParser(name="dup", priority=40)

# One name at equal priority, for the arbitrary-but-deterministic tie-break.
TIE: Parser = RecordingParser(name="tie", priority=25)

